    public static int[] columnMins(int[][] grid) {
        int[] mins = new int[grid[0].length];
        for (int c = 0; c < grid[0].length; c++) {
            int m = grid[0][c];
            for (int r = 1; r < grid.length; r++) {
                if (grid[r][c] < m) {
                    m = grid[r][c];
                }
            }
            mins[c] = m;
        }
        return mins;
    }
